// src/services/api.js
const API_BASE_URL = process.env.REACT_APP_API_URL || 'https://tz-prod.intelligra.io';
const API_ENDPOINT = process.env.REACT_APP_API_ENDPOINT || '/sharedService/api/Insurance/get-claim-details';
const ENABLE_MOCK = process.env.REACT_APP_ENABLE_MOCK_DATA === 'true';
const ENABLE_LOGGING = process.env.REACT_APP_ENABLE_LOGGING === 'true';

export const api = {
  // Real API call
  getClaim: async (msisdn) => {
    try {
      if (ENABLE_LOGGING) {
        console.log(` Fetching claim for: ${msisdn}`);
        console.log(` API URL: ${API_BASE_URL}${API_ENDPOINT}?msisdn=${msisdn}`);
      }

      const response = await fetch(
        `${API_BASE_URL}${API_ENDPOINT}?msisdn=${msisdn}`
      );
      
      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }
      
      const data = await response.json();
      
      if (ENABLE_LOGGING) {
        console.log(' Claim data received:', data);
      }
      
      return data;
    } catch (error) {
      console.error(' API Error:', error);
      throw error;
    }
  },

  // Mock for development
  getClaimMock: async (msisdn) => {
    if (ENABLE_LOGGING) {
      console.log(` Using mock data for: ${msisdn}`);
    }

    return new Promise((resolve) => {
      setTimeout(() => {
        const mockData = {
          id: 52874,
          created_at: '2025-12-03 13:53:34',
          updated_at: '2025-12-03 13:53:34',
          covernote_request: {
            CoverNoteHeader: {
              provider: 'INTELLIGRA',
              request_id: 'a5401463-c43a-4b8f-b570-32ee200e3989',
              covernote_type: 1,
              prev_cover_note_reference_number: ''
            },
            CoverNoteDetails: {
              endorsement_type: null,
              endorsement_reason: '',
              endorsement_premium_earned: '',
              imei_1: '356136680338086',
              imei_2: '',
              cover_note_start_date: '2025-12-03 13:53',
              cover_note_end_date: '2026-12-02 23:59:59'
            },
            PolicyHolder: {
              region: 'Dar es Salaam',
              district: 'Ubungo',
              street: 'Ubungo',
              policy_holder_name: 'Lupo Chambaka',
              policy_holder_type: 1,
              id_type: 1,
              id_number: '19720204151030000225',
              phone_number: '255781518973',
              postal_address: '',
              email_address: ''
            },
            RiskCovered: {
              model_code: 'BC00460181',
              premium_rate: 0.025,
              premium_excluding_tax: 8750.0,
              premium_including_tax: 10325.0,
              tax_rate: 0.18,
              tax_amount: 1575.0
            }
          },
          message: 'Successful',
          processed: null,
          processed_date: '2025-12-03 13:54:02',
          status: 'PINS000',
          covert_note_number: '135402-251203-592423',
          msisdn: '255781518973'
        };

        if (ENABLE_LOGGING) {
          console.log(' Mock data generated:', mockData);
        }

        resolve(mockData);
      }, 400);
    });
  },

  // Get claim with environment-aware fallback
  getClaimWithFallback: async (msisdn) => {
    // If mock mode is enabled, use mock data
    if (ENABLE_MOCK) {
      return api.getClaimMock(msisdn);
    }
    
    // Otherwise try real API
    try {
      return await api.getClaim(msisdn);
    } catch (error) {
      console.warn(' Real API failed, falling back to mock data');
      return api.getClaimMock(msisdn);
    }
  }
};

export default api;
